insert into public.talent_readiness_tasks(code,version,skill,definition,answer_key,review_guide) values('accountant-close-v2-a',2,'month_end_closing','{"title":{"ar":"إقفال أكتوبر — محاسب مبتدئ","en":"October close — junior accountant"},"minutes":35,"introduction":{"ar":"أنت محاسب جديد في منشأة خدمات، ومطلوب إقفال 31 أكتوبر على أساس الاستحقاق. راجع المستندات والسجلات التالية وأنشئ قيد التصحيح أو التسوية لكل عملية كما هي مسجلة الآن. جميع المبالغ بالريال، والضرائب خارج نطاق الحالة. استخدم قيدًا صافيًا واحدًا لكل عملية؛ لا تعكس العملية كاملة ثم تعيد تسجيلها. كل عملية مستقلة ولا توجد فروق أخرى. حسابات قائمة الدخل لم تُقفل بعد.","en":"You are a junior accountant closing 31 October on the accrual basis. Review the documents and current postings, then construct the correction or adjustment needed for each. All amounts are SAR; taxes are outside scope. Use one net correcting entry per transaction, not a full reversal and repost. Transactions are independent and there are no other differences. Income statement accounts have not yet been closed."},"columns":{"ar":["المستند / العملية","الوقائع المثبتة","التسجيل الحالي"],"en":["Document / transaction","Established facts","Current posting"]},"rows":[["1",{"ar":"عقد إيجار من 1 أكتوبر حتى 30 سبتمبر التالي. دُفع 12000 مقدمًا لتغطية 12 شهرًا متساوية؛ لا توجد تأمينات أو خدمات إضافية.","en":"Rent contract runs 1 October to the following 30 September. 12000 paid upfront for 12 equal months; no deposits or additional services."},{"ar":"مدين مصروف إيجار 12000 / دائن البنك 12000","en":"Debit rent expense 12000 / credit bank 12000"}],["2",{"ar":"فاتورة كهرباء 900 تخص استهلاك أكتوبر بالكامل، وصلت 5 نوفمبر قبل اعتماد إقفال أكتوبر. الاستهلاك مؤكد ولم تُدفع الفاتورة.","en":"Electricity invoice 900, entirely for October consumption, received 5 November before October close approval. Consumption is confirmed; invoice is unpaid."},{"ar":"لم تُسجل أي عملية. استخدم حساب مصروفات مستحقة للالتزام.","en":"No entry recorded. Use accrued expenses for the liability."}],["3",{"ar":"وصل 4000 يوم 28 أكتوبر مقابل خدمات ستقدم بالكامل في نوفمبر. حتى 31 أكتوبر لم تقدم أي خدمة للعميل.","en":"4000 received on 28 October for services wholly scheduled for November. No service delivered by 31 October."},{"ar":"مدين البنك 4000 / دائن إيراد خدمات 4000","en":"Debit bank 4000 / credit service revenue 4000"}],["4",{"ar":"تحصيل 2500 من عميل مقابل فاتورة سبتمبر. إيراد الفاتورة ومديونية العميل سُجلا بصورة صحيحة في سبتمبر.","en":"2500 collected against a September invoice. Revenue and receivable were correctly recorded in September."},{"ar":"مدين البنك 2500 / دائن إيراد خدمات 2500","en":"Debit bank 2500 / credit service revenue 2500"}]],"fields":[{"key":"e1_debit","type":"select","label":{"ar":"1. عقد الإيجار — الحساب المدين","en":"1. Rent contract — debit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e1_credit","type":"select","label":{"ar":"1. عقد الإيجار — الحساب الدائن","en":"1. Rent contract — credit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e1_amount","type":"number","label":{"ar":"1. مبلغ القيد التصحيحي / قيد التسوية","en":"1. Correction / adjustment amount"},"weight":8},{"key":"e1_reason","type":"text","label":{"ar":"1. فسّر المعالجة وتوقيت الاعتراف وأثرها على الحسابات","en":"1. Explain the treatment, recognition timing and account impact"},"weight":0,"minLength":60,"maxLength":1200},{"key":"e2_debit","type":"select","label":{"ar":"2. الكهرباء — الحساب المدين","en":"2. Electricity — debit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e2_credit","type":"select","label":{"ar":"2. الكهرباء — الحساب الدائن","en":"2. Electricity — credit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e2_amount","type":"number","label":{"ar":"2. مبلغ القيد التصحيحي / قيد التسوية","en":"2. Correction / adjustment amount"},"weight":8},{"key":"e2_reason","type":"text","label":{"ar":"2. فسّر المعالجة وتوقيت الاعتراف وأثرها على الحسابات","en":"2. Explain the treatment, recognition timing and account impact"},"weight":0,"minLength":60,"maxLength":1200},{"key":"e3_debit","type":"select","label":{"ar":"3. المبلغ المقبوض قبل تقديم الخدمة — الحساب المدين","en":"3. Cash received before service delivery — debit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e3_credit","type":"select","label":{"ar":"3. المبلغ المقبوض قبل تقديم الخدمة — الحساب الدائن","en":"3. Cash received before service delivery — credit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e3_amount","type":"number","label":{"ar":"3. مبلغ القيد التصحيحي / قيد التسوية","en":"3. Correction / adjustment amount"},"weight":8},{"key":"e3_reason","type":"text","label":{"ar":"3. فسّر المعالجة وتوقيت الاعتراف وأثرها على الحسابات","en":"3. Explain the treatment, recognition timing and account impact"},"weight":0,"minLength":60,"maxLength":1200},{"key":"e4_debit","type":"select","label":{"ar":"4. تحصيل فاتورة سابقة — الحساب المدين","en":"4. Collection of a prior invoice — debit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e4_credit","type":"select","label":{"ar":"4. تحصيل فاتورة سابقة — الحساب الدائن","en":"4. Collection of a prior invoice — credit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e4_amount","type":"number","label":{"ar":"4. مبلغ القيد التصحيحي / قيد التسوية","en":"4. Correction / adjustment amount"},"weight":8},{"key":"e4_reason","type":"text","label":{"ar":"4. فسّر المعالجة وتوقيت الاعتراف وأثرها على الحسابات","en":"4. Explain the treatment, recognition timing and account impact"},"weight":0,"minLength":60,"maxLength":1200},{"key":"profit_direction","type":"select","label":{"ar":"بعد القيود الأربعة، اتجاه التغير في صافي ربح أكتوبر مقارنة بالدفاتر الحالية","en":"After all four entries, direction of change in October net profit versus the current books"},"options":[{"value":"up","ar":"زيادة","en":"Increase"},{"value":"down","ar":"نقص","en":"Decrease"},{"value":"same","ar":"لا تغير","en":"No change"}],"weight":5},{"key":"profit_amount","type":"number","label":{"ar":"المقدار المطلق للتغير في صافي ربح أكتوبر","en":"Absolute amount of change in October net profit"},"weight":5},{"key":"assets_direction","type":"select","label":{"ar":"بعد القيود الأربعة، اتجاه التغير في إجمالي الأصول مقارنة بالدفاتر الحالية","en":"After all four entries, direction of change in Total assets versus the current books"},"options":[{"value":"up","ar":"زيادة","en":"Increase"},{"value":"down","ar":"نقص","en":"Decrease"},{"value":"same","ar":"لا تغير","en":"No change"}],"weight":5},{"key":"assets_amount","type":"number","label":{"ar":"المقدار المطلق للتغير في إجمالي الأصول","en":"Absolute amount of change in Total assets"},"weight":5}],"rationale":{"ar":"موقف إضافي لا يدخل في حساب الأثر العددي أعلاه: وصل طلب شراء مسودة لصيانة بقيمة 3,000 ريال، وقال المشرف إن العمل «ربما اكتمل» في أكتوبر، ولا يوجد محضر إنجاز أو فاتورة. ما الأدلة التي تطلبها، وكيف تحدد فترة الاعتراف والالتزام؟ اشرح قرارك إذا ثبت الإنجاز قبل نهاية أكتوبر، وإذا لم يثبت. ثم وضح كيف تتحقق من توازن قيودك وأثرها قبل الاعتماد.","en":"Additional scenario, excluded from the numerical impact above: a draft maintenance purchase order for SAR 3,000 arrives; a supervisor says the work \"may have finished\" in October. There is no completion report or invoice. What evidence do you request, and how do you determine recognition period and liability? Explain your decision if October completion is established and if it is not. Then explain how you verify balanced entries and their impact before approval."},"rationaleMinLength":180,"guidance":{"ar":"راجع أساس الاستحقاق والتمييز بين المصروف والأصل، وبين الإيراد والالتزام. حلل كل عملية من التسجيل الحالي ثم اجمع أثر القيود على الربح والأصول، وراجع ملاحظات المراجع لكل جزء.","en":"Review accrual accounting, expense versus asset, and revenue versus liability. Start each correction from the actual current posting, aggregate effects on profit and assets, and review section-specific human feedback."},"threshold":80}'::jsonb,'{"e1_debit":"1300","e1_credit":"5000","e1_amount":11000,"e2_debit":"5100","e2_credit":"2100","e2_amount":900,"e3_debit":"4000","e3_credit":"2200","e3_amount":4000,"e4_debit":"4000","e4_credit":"1200","e4_amount":2500,"profit_direction":"up","profit_amount":3600,"assets_direction":"up","assets_amount":8500}'::jsonb,'{"ar":"راجع تبرير كل قيد؛ صحة اختيارات الحسابات وحدها لا تكفي. يجب تفسير توزيع الإيجار على مدة الانتفاع، استحقاق الكهرباء رغم تأخر الفاتورة، التزام الخدمة قبل أدائها، وعدم تكرار الإيراد عند تحصيل مديونية سابقة. في الموقف الإضافي: اطلب أدلة الإنجاز والفترة والتكلفة والاعتماد؛ لا تثبت مصروفًا من مسودة شراء وحدها ولا تؤجل مصروفًا مؤكد الاستحقاق لمجرد غياب الفاتورة. تحقق من تفسير أثر القيود مجتمعة. دوّن الملاحظات لكل جزء، وأعد الحالة للتطوير إذا كان الشرح لا يدعم صحة المعالجة.","en":"Review the explanation for every entry; correct account selections alone are insufficient. Require benefit-period allocation for rent, electricity accrual despite late invoicing, an obligation before service delivery, and no second revenue recognition on collection. For missing evidence, request completion, cutoff, amount and approval support; a draft order alone is insufficient, while confirmed accrued expense must not be deferred solely because an invoice is missing. Check the combined financial-statement impact and give section-specific feedback. Mark NeedsDevelopment when explanations do not support the treatment."}'::jsonb) on conflict(code) do nothing;
insert into public.talent_readiness_tasks(code,version,skill,definition,answer_key,review_guide) values('accountant-close-v2-b',2,'month_end_closing','{"title":{"ar":"إقفال أكتوبر — محاسب مبتدئ","en":"October close — junior accountant"},"minutes":35,"introduction":{"ar":"أنت محاسب جديد في منشأة خدمات، ومطلوب إقفال 31 أكتوبر على أساس الاستحقاق. راجع المستندات والسجلات التالية وأنشئ قيد التصحيح أو التسوية لكل عملية كما هي مسجلة الآن. جميع المبالغ بالريال، والضرائب خارج نطاق الحالة. استخدم قيدًا صافيًا واحدًا لكل عملية؛ لا تعكس العملية كاملة ثم تعيد تسجيلها. كل عملية مستقلة ولا توجد فروق أخرى. حسابات قائمة الدخل لم تُقفل بعد.","en":"You are a junior accountant closing 31 October on the accrual basis. Review the documents and current postings, then construct the correction or adjustment needed for each. All amounts are SAR; taxes are outside scope. Use one net correcting entry per transaction, not a full reversal and repost. Transactions are independent and there are no other differences. Income statement accounts have not yet been closed."},"columns":{"ar":["المستند / العملية","الوقائع المثبتة","التسجيل الحالي"],"en":["Document / transaction","Established facts","Current posting"]},"rows":[["1",{"ar":"عقد إيجار من 1 أكتوبر حتى 30 سبتمبر التالي. دُفع 6000 مقدمًا لتغطية 12 شهرًا متساوية؛ لا توجد تأمينات أو خدمات إضافية.","en":"Rent contract runs 1 October to the following 30 September. 6000 paid upfront for 12 equal months; no deposits or additional services."},{"ar":"مدين مصروف إيجار 6000 / دائن البنك 6000","en":"Debit rent expense 6000 / credit bank 6000"}],["2",{"ar":"فاتورة كهرباء 1400 تخص استهلاك أكتوبر بالكامل، وصلت 5 نوفمبر قبل اعتماد إقفال أكتوبر. الاستهلاك مؤكد ولم تُدفع الفاتورة.","en":"Electricity invoice 1400, entirely for October consumption, received 5 November before October close approval. Consumption is confirmed; invoice is unpaid."},{"ar":"لم تُسجل أي عملية. استخدم حساب مصروفات مستحقة للالتزام.","en":"No entry recorded. Use accrued expenses for the liability."}],["3",{"ar":"وصل 7000 يوم 28 أكتوبر مقابل خدمات ستقدم بالكامل في نوفمبر. حتى 31 أكتوبر لم تقدم أي خدمة للعميل.","en":"7000 received on 28 October for services wholly scheduled for November. No service delivered by 31 October."},{"ar":"مدين البنك 7000 / دائن إيراد خدمات 7000","en":"Debit bank 7000 / credit service revenue 7000"}],["4",{"ar":"تحصيل 3500 من عميل مقابل فاتورة سبتمبر. إيراد الفاتورة ومديونية العميل سُجلا بصورة صحيحة في سبتمبر.","en":"3500 collected against a September invoice. Revenue and receivable were correctly recorded in September."},{"ar":"مدين البنك 3500 / دائن إيراد خدمات 3500","en":"Debit bank 3500 / credit service revenue 3500"}]],"fields":[{"key":"e1_debit","type":"select","label":{"ar":"1. عقد الإيجار — الحساب المدين","en":"1. Rent contract — debit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e1_credit","type":"select","label":{"ar":"1. عقد الإيجار — الحساب الدائن","en":"1. Rent contract — credit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e1_amount","type":"number","label":{"ar":"1. مبلغ القيد التصحيحي / قيد التسوية","en":"1. Correction / adjustment amount"},"weight":8},{"key":"e1_reason","type":"text","label":{"ar":"1. فسّر المعالجة وتوقيت الاعتراف وأثرها على الحسابات","en":"1. Explain the treatment, recognition timing and account impact"},"weight":0,"minLength":60,"maxLength":1200},{"key":"e2_debit","type":"select","label":{"ar":"2. الكهرباء — الحساب المدين","en":"2. Electricity — debit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e2_credit","type":"select","label":{"ar":"2. الكهرباء — الحساب الدائن","en":"2. Electricity — credit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e2_amount","type":"number","label":{"ar":"2. مبلغ القيد التصحيحي / قيد التسوية","en":"2. Correction / adjustment amount"},"weight":8},{"key":"e2_reason","type":"text","label":{"ar":"2. فسّر المعالجة وتوقيت الاعتراف وأثرها على الحسابات","en":"2. Explain the treatment, recognition timing and account impact"},"weight":0,"minLength":60,"maxLength":1200},{"key":"e3_debit","type":"select","label":{"ar":"3. المبلغ المقبوض قبل تقديم الخدمة — الحساب المدين","en":"3. Cash received before service delivery — debit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e3_credit","type":"select","label":{"ar":"3. المبلغ المقبوض قبل تقديم الخدمة — الحساب الدائن","en":"3. Cash received before service delivery — credit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e3_amount","type":"number","label":{"ar":"3. مبلغ القيد التصحيحي / قيد التسوية","en":"3. Correction / adjustment amount"},"weight":8},{"key":"e3_reason","type":"text","label":{"ar":"3. فسّر المعالجة وتوقيت الاعتراف وأثرها على الحسابات","en":"3. Explain the treatment, recognition timing and account impact"},"weight":0,"minLength":60,"maxLength":1200},{"key":"e4_debit","type":"select","label":{"ar":"4. تحصيل فاتورة سابقة — الحساب المدين","en":"4. Collection of a prior invoice — debit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e4_credit","type":"select","label":{"ar":"4. تحصيل فاتورة سابقة — الحساب الدائن","en":"4. Collection of a prior invoice — credit account"},"options":[{"value":"1001","ar":"البنك","en":"Bank"},{"value":"1200","ar":"العملاء","en":"Accounts receivable"},{"value":"1300","ar":"إيجار مدفوع مقدمًا","en":"Prepaid rent"},{"value":"1400","ar":"المخزون","en":"Inventory"},{"value":"2100","ar":"مصروفات مستحقة","en":"Accrued expenses"},{"value":"2200","ar":"إيراد مؤجل / دفعات عملاء مقدمة","en":"Deferred revenue / customer advances"},{"value":"2300","ar":"الموردون","en":"Accounts payable"},{"value":"3000","ar":"رأس المال","en":"Capital"},{"value":"4000","ar":"إيراد خدمات","en":"Service revenue"},{"value":"5000","ar":"مصروف إيجار","en":"Rent expense"},{"value":"5100","ar":"مصروف كهرباء","en":"Electricity expense"}],"weight":6},{"key":"e4_amount","type":"number","label":{"ar":"4. مبلغ القيد التصحيحي / قيد التسوية","en":"4. Correction / adjustment amount"},"weight":8},{"key":"e4_reason","type":"text","label":{"ar":"4. فسّر المعالجة وتوقيت الاعتراف وأثرها على الحسابات","en":"4. Explain the treatment, recognition timing and account impact"},"weight":0,"minLength":60,"maxLength":1200},{"key":"profit_direction","type":"select","label":{"ar":"بعد القيود الأربعة، اتجاه التغير في صافي ربح أكتوبر مقارنة بالدفاتر الحالية","en":"After all four entries, direction of change in October net profit versus the current books"},"options":[{"value":"up","ar":"زيادة","en":"Increase"},{"value":"down","ar":"نقص","en":"Decrease"},{"value":"same","ar":"لا تغير","en":"No change"}],"weight":5},{"key":"profit_amount","type":"number","label":{"ar":"المقدار المطلق للتغير في صافي ربح أكتوبر","en":"Absolute amount of change in October net profit"},"weight":5},{"key":"assets_direction","type":"select","label":{"ar":"بعد القيود الأربعة، اتجاه التغير في إجمالي الأصول مقارنة بالدفاتر الحالية","en":"After all four entries, direction of change in Total assets versus the current books"},"options":[{"value":"up","ar":"زيادة","en":"Increase"},{"value":"down","ar":"نقص","en":"Decrease"},{"value":"same","ar":"لا تغير","en":"No change"}],"weight":5},{"key":"assets_amount","type":"number","label":{"ar":"المقدار المطلق للتغير في إجمالي الأصول","en":"Absolute amount of change in Total assets"},"weight":5}],"rationale":{"ar":"موقف إضافي لا يدخل في حساب الأثر العددي أعلاه: وصل طلب شراء مسودة لصيانة بقيمة 3,000 ريال، وقال المشرف إن العمل «ربما اكتمل» في أكتوبر، ولا يوجد محضر إنجاز أو فاتورة. ما الأدلة التي تطلبها، وكيف تحدد فترة الاعتراف والالتزام؟ اشرح قرارك إذا ثبت الإنجاز قبل نهاية أكتوبر، وإذا لم يثبت. ثم وضح كيف تتحقق من توازن قيودك وأثرها قبل الاعتماد.","en":"Additional scenario, excluded from the numerical impact above: a draft maintenance purchase order for SAR 3,000 arrives; a supervisor says the work \"may have finished\" in October. There is no completion report or invoice. What evidence do you request, and how do you determine recognition period and liability? Explain your decision if October completion is established and if it is not. Then explain how you verify balanced entries and their impact before approval."},"rationaleMinLength":180,"guidance":{"ar":"راجع أساس الاستحقاق والتمييز بين المصروف والأصل، وبين الإيراد والالتزام. حلل كل عملية من التسجيل الحالي ثم اجمع أثر القيود على الربح والأصول، وراجع ملاحظات المراجع لكل جزء.","en":"Review accrual accounting, expense versus asset, and revenue versus liability. Start each correction from the actual current posting, aggregate effects on profit and assets, and review section-specific human feedback."},"threshold":80}'::jsonb,'{"e1_debit":"1300","e1_credit":"5000","e1_amount":5500,"e2_debit":"5100","e2_credit":"2100","e2_amount":1400,"e3_debit":"4000","e3_credit":"2200","e3_amount":7000,"e4_debit":"4000","e4_credit":"1200","e4_amount":3500,"profit_direction":"down","profit_amount":6400,"assets_direction":"up","assets_amount":2000}'::jsonb,'{"ar":"راجع تبرير كل قيد؛ صحة اختيارات الحسابات وحدها لا تكفي. يجب تفسير توزيع الإيجار على مدة الانتفاع، استحقاق الكهرباء رغم تأخر الفاتورة، التزام الخدمة قبل أدائها، وعدم تكرار الإيراد عند تحصيل مديونية سابقة. في الموقف الإضافي: اطلب أدلة الإنجاز والفترة والتكلفة والاعتماد؛ لا تثبت مصروفًا من مسودة شراء وحدها ولا تؤجل مصروفًا مؤكد الاستحقاق لمجرد غياب الفاتورة. تحقق من تفسير أثر القيود مجتمعة. دوّن الملاحظات لكل جزء، وأعد الحالة للتطوير إذا كان الشرح لا يدعم صحة المعالجة.","en":"Review the explanation for every entry; correct account selections alone are insufficient. Require benefit-period allocation for rent, electricity accrual despite late invoicing, an obligation before service delivery, and no second revenue recognition on collection. For missing evidence, request completion, cutoff, amount and approval support; a draft order alone is insufficient, while confirmed accrued expense must not be deferred solely because an invoice is missing. Check the combined financial-statement impact and give section-specific feedback. Mark NeedsDevelopment when explanations do not support the treatment."}'::jsonb) on conflict(code) do nothing;
update public.talent_readiness_tasks set active=false where code in ('invoice-review-v1','bank-reconciliation-v1');
create or replace function public.get_my_accountant_readiness() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_candidate uuid; v_case text;
begin
  if auth.uid() is null then raise exception using errcode='42501', message='Candidate authentication required'; end if;
  select id into v_candidate from public.talent_candidates where auth_user_id=auth.uid();
  if v_candidate is null then raise exception using errcode='P0002',message='Complete your Talent profile first'; end if;
  v_case:='accountant-close-v2-' || case when get_byte(decode(replace(v_candidate::text,'-',''),'hex'),0)%2=0 then 'a' else 'b' end;
  return jsonb_build_object('tasks',coalesce((select jsonb_agg(jsonb_build_object(
    'code',t.code,'version',t.version,'skill',t.skill,'definition',t.definition,'archived',not t.active,
    'attempt',(select to_jsonb(a)-'candidate_id' from public.talent_readiness_attempts a where a.candidate_id=v_candidate and a.task_code=t.code)
  ) order by t.version desc,t.code) from public.talent_readiness_tasks t
  where (t.active and t.code=v_case) or (not t.active and exists(select 1 from public.talent_readiness_attempts a where a.candidate_id=v_candidate and a.task_code=t.code))),'[]'::jsonb));
end; $$;
create or replace function public.save_accountant_readiness(
  p_task_code text, p_answers jsonb, p_revision integer, p_submit boolean default false, p_consent boolean default false
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_candidate uuid; v_task public.talent_readiness_tasks%rowtype; v_attempt public.talent_readiness_attempts%rowtype;
  v_field jsonb; v_value jsonb; v_key text; v_ok boolean; v_score integer:=0; v_evidence jsonb:='[]';
begin
  if auth.uid() is null then raise exception using errcode='42501',message='Candidate authentication required'; end if;
  select id into v_candidate from public.talent_candidates where auth_user_id=auth.uid() for update;
  if v_candidate is null then raise exception using errcode='P0002',message='Complete your Talent profile first'; end if;
  if p_task_code like 'accountant-close-v2-%' and p_task_code <> ('accountant-close-v2-' || case when get_byte(decode(replace(v_candidate::text,'-',''),'hex'),0)%2=0 then 'a' else 'b' end) then
    raise exception using errcode='42501',message='Use your assigned case'; end if;
  select * into v_task from public.talent_readiness_tasks where code=p_task_code and active;
  if not found then raise exception using errcode='22023',message='Task unavailable'; end if;
  if p_answers is null or jsonb_typeof(p_answers)<>'object' or octet_length(p_answers::text)>40000
    or p_revision is null or p_revision<0 or p_submit is null then
    raise exception using errcode='22023',message='Invalid answers';
  end if;
  for v_key in select jsonb_object_keys(p_answers) loop
    if v_key<>'rationale' and not exists(select 1 from jsonb_array_elements(v_task.definition->'fields') f where f->>'key'=v_key) then
      raise exception using errcode='22023',message='Unknown answer field';
    end if;
  end loop;
  if p_answers ? 'rationale' and (jsonb_typeof(p_answers->'rationale')<>'string' or length(p_answers->>'rationale')>2000) then
    raise exception using errcode='22023',message='Explanation must be text up to 2000 characters';
  end if;
  if p_submit and length(btrim(coalesce(p_answers->>'rationale','')))<coalesce((v_task.definition->>'rationaleMinLength')::integer,30) then
    raise exception using errcode='22023',message='Explain your approach using the minimum length shown in the task';
  end if;
  for v_field in select value from jsonb_array_elements(v_task.definition->'fields') loop
    v_key:=v_field->>'key'; v_value:=p_answers->v_key;
    if v_value is null or v_value='null'::jsonb or v_value='""'::jsonb then
      if p_submit then raise exception using errcode='22023',message='Complete every answer'; end if;
      continue;
    end if;
    if v_field->>'type'='text' then
      if jsonb_typeof(v_value)<>'string' or length(v_value#>>'{}')>coalesce((v_field->>'maxLength')::integer,1200) or
        (p_submit and length(btrim(v_value#>>'{}'))<coalesce((v_field->>'minLength')::integer,60)) then
        raise exception using errcode='22023',message='Provide a substantive explanation for every entry'; end if;
      continue;
    elsif v_field->>'type'='number' then
      if jsonb_typeof(v_value) not in ('string','number') or (v_value#>>'{}') !~ '^[0-9]{1,9}(\.[0-9]{1,2})?$' then
        raise exception using errcode='22023',message='Enter valid nonnegative amounts with up to two decimals';
      end if;
      v_ok:=(v_value#>>'{}')::numeric=(v_task.answer_key->>v_key)::numeric;
    else
      if jsonb_typeof(v_value)<>'string' or not exists(select 1 from jsonb_array_elements(v_field->'options') o where o->>'value'=v_value#>>'{}') then
        raise exception using errcode='22023',message='Select a listed option';
      end if;
      v_ok:=v_value=v_task.answer_key->v_key;
    end if;
    if v_ok then v_score:=v_score+(v_field->>'weight')::integer; end if;
    v_evidence:=v_evidence||jsonb_build_array(jsonb_build_object('key',v_key,'correct',v_ok,'earned',case when v_ok then (v_field->>'weight')::integer else 0 end,'possible',(v_field->>'weight')::integer));
  end loop;
  select * into v_attempt from public.talent_readiness_attempts where candidate_id=v_candidate and task_code=p_task_code for update;
  if not found then
    if not coalesce(p_consent,false) then raise exception using errcode='22023',message='Consent to private assessment and platform review is required'; end if;
    if p_revision<>0 then raise exception using errcode='40001',message='Draft changed; reload before saving'; end if;
    insert into public.talent_readiness_attempts(candidate_id,task_code) values(v_candidate,p_task_code) returning * into v_attempt;
  end if;
  if v_attempt.status='Submitted' then
    if p_submit and v_attempt.answers=p_answers then return to_jsonb(v_attempt)-'candidate_id'; end if;
    raise exception using errcode='22023',message='Submitted answers are locked';
  end if;
  if v_attempt.revision<>p_revision then raise exception using errcode='40001',message='Draft changed; reload before saving'; end if;
  update public.talent_readiness_attempts set answers=p_answers,revision=revision+1,updated_at=now(),
    status=case when p_submit then 'Submitted' else 'Draft' end,
    submitted_at=case when p_submit then now() else null end,
    objective_score=case when p_submit then v_score else null end,
    evidence=case when p_submit then v_evidence else null end
  where id=v_attempt.id returning * into v_attempt;
  return to_jsonb(v_attempt)-'candidate_id';
end; $$;
